CREATE TABLE public.emergency_profiles (user_id uuid PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(data) = 'object' AND octet_length(data::text) <= 20000), sharing_consent boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.emergency_profiles TO authenticated; GRANT ALL ON public.emergency_profiles TO service_role; ALTER TABLE public.emergency_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own emergency profile" ON public.emergency_profiles FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "Create own emergency profile" ON public.emergency_profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Update own emergency profile" ON public.emergency_profiles FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Delete own emergency profile" ON public.emergency_profiles FOR DELETE TO authenticated USING (auth.uid() = user_id);